mod solution;

fn valid(_input: &str, actual: &str, expected: &str) -> bool { actual == expected }

fn main() {
    let cases = [
        ("edges=0->1:4,0->2:5,1->2:-2","0,4,2"),
        ("edges=0->1:2,1->2:3","0,2,5"),
        ("edges=0->1:2,1->2:-1","0,2,1"),
        ("edges=0->1:0,1->2:0","0,0,0"),
        ("edges=0->1:9,0->2:2,2->1:3","0,5,2"),
        ("edges=1->2:1,0->1:1","0,1,2"),
        ("edges=0->1:2,0->2:3,2->1:-2","0,1,3"),
        ("  \nedges=0->1:4,0->2:5,1->2:-2\n  ","0,4,2"),
        ("\nedges=0->1:9,0->2:2,2->1:3\n","0,5,2")
    ];
    for (i,(input,expected)) in cases.iter().enumerate() {
        let actual = solution::solve(input);
        if !valid(input,&actual,expected) { eprintln!("PRIVATE CASE {} FAILED",i+1); std::process::exit(1); }
    }
    println!("PASS bellman-ford");
}
